def maxCoinsAroundWalls(grid):
    n = len(grid[0])
    best = [-1] * n
    for r, row in enumerate(grid):
        for c in range(n):
            if row[c] == -1:
                best[c] = -1
                continue
            if r == 0 and c == 0:
                best[c] = row[c]
                continue
            m = best[c]
            if c > 0 and best[c - 1] > m:
                m = best[c - 1]
            best[c] = m + row[c] if m >= 0 else -1
    return best[-1]
